create or replace function public.admin_update_store_product(p_id text,p_name text,p_description text,p_price integer,p_active boolean,p_probability numeric default null,p_min integer default null,p_max integer default null,p_stats text[] default null,p_slot text default null,p_quality text default null,p_bonuses jsonb default '{}',p_disciplines text[] default '{}') returns void language plpgsql security definer set search_path=public as $$begin perform require_super_admin();if p_price<0 or(p_probability is not null and(p_probability<0 or p_probability>1))or(p_min is not null and p_max<p_min)then raise exception 'Product values are outside supported ranges';end if;update store_products set name=left(trim(p_name),100),description=case when coalesce(p_description,'')=''then description else left(p_description,500)end,price=p_price,active=p_active,feed_success_probability=case when department='feed'then p_probability else feed_success_probability end,development_min=case when department='feed'then p_min else development_min end,development_max=case when department='feed'then p_max else development_max end,eligible_stats=coalesce(p_stats,eligible_stats),tack_slot=coalesce(p_slot,tack_slot),quality=coalesce(p_quality,quality),tack_bonuses=case when coalesce(p_bonuses,'{}')='{}'::jsonb then tack_bonuses else p_bonuses end,discipline_orientation=case when coalesce(cardinality(p_disciplines),0)=0 then discipline_orientation else p_disciplines end where id=p_id;if not found then raise exception 'Store product not found';end if;end$$;
